from review import card,save,DATE,DIRECTORY,write
import json

def b(t,s,r=None):
    d=dict(title=t,text=s)
    if r:d['citation']=r
    return d
def sm(s,r):return dict(sentences=s,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=r)
def imp(c,s):return dict(score=c['importance']['score'],method='editorial',reason=s+' Existing numerical score retained.',assessed_on=DATE)

i='TCS-2069';_,c=card(i);refs=c['references']
refs[0]['locator']='ALT 2024: Definition 1 and Section 5.3 read. The question concerns generic pure-private online learning; the subsequent NeurIPS paper explicitly answers it for every pure privately PAC-learnable class against oblivious adversaries.'
refs.append(dict(id='solution',title='The Limits of Differential Privacy in Online Learning',authors='Bo Li, Wei Wang, Peng Ye',year=2024,url='https://proceedings.neurips.cc/paper_files/paper/2024/hash/77fa8253adfc8b33209639f3e9985741-Abstract-Conference.html',pdf_url='https://proceedings.nips.cc/paper_files/paper/2024/file/77fa8253adfc8b33209639f3e9985741-Paper-Conference.pdf',locator='NeurIPS 2024: Section 2 model and privacy, Definition 3.1, Theorem 3.3 and Appendix D.1 read; introduction explicitly identifies the Dmitriev–Szabó–Sanyal question. Theorem 3.5 distinguishes adaptive adversaries.'))
save(i,dict(title='Generic pure-private online learning against oblivious adversaries',status='resolved',formal='Historical question, resolved positively: does every binary hypothesis class H of finite representation dimension admit, for each fixed ε>0, a pure ε-differentially private online learner with o(T) expected prediction mistakes on every realizable length-T sequence fixed by an oblivious adversary? The learner may know T, may output hypotheses outside H, and has no computational-efficiency requirement.',definitions='Let X be an instance domain and H⊆{0,1}^X. Before learning starts, an oblivious adversary fixes h*∈H and x_1,…,x_T∈X, with labels y_t=h*(x_t). In round t the randomized learner outputs a hypothesis h_t:X→{0,1} using only its previous observations, then receives (x_t,y_t); its mistake count is Σ_t 1[h_t(x_t)≠y_t]. The guarantee is a worst-case bound on the expectation over the learner’s randomness. Pure ε-differential privacy means that for any two length-T labeled sequences S,S′ differing in one example and any event E of full output sequences, Pr[A(S)∈E]≤e^ε Pr[A(S′)∈E]. This privacy condition applies to all labeled sequences, including unrealizable ones. A probabilistic representation of H is a distribution P over finite sets V of binary hypotheses such that, for every h*∈H and every distribution D on X, with probability at least 3/4 over V∼P some v∈V has Pr_{x∼D}[v(x)≠h*(x)]≤1/4. Its size is the largest log|V| in its support, and RepDim(H) is the infimum of these sizes. Finite representation dimension is the class condition characterizing pure private PAC learnability. The target o(T) is for each fixed H and ε as T tends to infinity, uniformly over the realizable oblivious sequences; it does not mean a finite mistake bound independent of T.',question_type='yes_no',answer_criterion='The published affirmative theorem establishes an ε-private learner with expected mistake bound O(log²T·(RepDim(H)+log log T)²/ε) for large T, which is o(T) for every fixed finite RepDim(H) and ε>0. The result is information-theoretic and applies to oblivious realizable sequences.',context_blocks=[b('Privacy must cover the whole learning history','Each prediction hypothesis can reveal something about earlier training examples. The privacy budget here protects one changed example in the joint distribution of all hypotheses released during the T rounds.'),b('Generic means a class-wide theorem','The original paper asks whether one can go beyond constructions for particular classes. The answer covers every class of finite representation dimension, including infinite classes. Finite Littlestone dimension alone is not the hypothesis of this pure-privacy theorem.', 'solution'),b('The adversary convention matters','An oblivious adversary fixes its sequence before observing the learner’s random outputs. The same paper proves an obstruction for adaptive adversaries even for an infinite point-function class. Its generic positive result therefore does not establish the adaptive version.', 'solution'),b('Sublinear mistakes permit continued errors','A polylogarithmic number of expected mistakes grows with T, but its fraction of all T predictions tends to zero. This is enough for the source’s online-learnability criterion; the theorem does not promise efficient computation or a T-independent mistake bound.', 'solution')],why='Connects pure private PAC learnability to sequential prediction and identifies how the adversary’s access to the learner’s outputs changes that connection.',progress=[dict(date='2024',text='Dmitriev, Szabó and Sanyal ask for generic pure-private online learners after studying mistake lower bounds.',citation='primary'),dict(date='2024',text='Li, Wang and Ye answer the generic question for every finite-representation-dimension class against oblivious adversaries in NeurIPS 2024, Theorem 3.3.',citation='solution')],references=refs,status_note='Resolved by Li, Wang and Ye, NeurIPS 2024, Theorem 3.3. Checked the original Section 5.3 question, the follow-up’s explicit attribution, full privacy and online models, representation dimension and stated mistake bound. This is a published-theorem/model match, not an independent proof audit or proof-assistant certificate.',model_self_contained=True,requires_context=False,importance=imp(c,'A class-wide connection between pure private batch learning and online prediction.'),review_note='Recovered the generic question using the original online model and the paper that explicitly answers it. The finite-representation-dimension and oblivious-adversary conditions are essential; the record is resolved under those conditions.',working_summary=sm(['The learner predicts sequentially while protecting each training example across its entire released history.','The historical question asked for a generic pure-private online learner.','Li, Wang and Ye answered it for every class of finite representation dimension against oblivious adversaries.','Their expected mistake count is polylogarithmic in the number of rounds for each fixed class and privacy parameter.','The published theorem permits improper hypotheses and unrestricted computation; it does not cover adaptive adversaries.'],['primary','solution'])),notes=['Replaced an isolated generic-learners sentence with the precise historical class-wide question.','Defined full-history pure privacy, oblivious realizability, representation dimension and sublinear expected mistakes.','Matched the original question to NeurIPS 2024 Theorem 3.3 and marked the record resolved.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2411.05483'])

i='TCS-2089';_,c=card(i);refs=c['references']
refs[0]['locator']='ICALP 2024, article 114: Section 1 and Conjecture 1 read; the conjecture concerns integral Erdős–Pósa duality on every minor-closed environment class.'
refs.extend([dict(id='solution',title='Obstructions to Erdős–Pósa Dualities for Minors',authors='Christophe Paul, Evangelos Protopapas, Dimitrios M. Thilikos, Sebastian Wiederrecht',year=2024,url='https://arxiv.org/abs/2407.09671v2',locator='Version 2, 16 July 2024: definition of an EP-pair, Theorem 1.1, the finite obstruction-sequence family, Theorem 1.8 and the proof sketch of Theorem 1.1 read. Apply the theorem to the class of H-minor-free graphs; disconnected excluded minors are covered.'),dict(id='publication',title='Obstructions to Erdős–Pósa Dualities for Minors — FOCS publication',authors='Christophe Paul, Evangelos Protopapas, Dimitrios M. Thilikos, Sebastian Wiederrecht',year=2024,url='https://doi.org/10.1109/FOCS61266.2024.00013',locator='FOCS 2024, pp. 31–52. Publication confirmed against the official accepted-paper list and the KAIST author-institution record; full theorem checked in reference solution.')])
save(i,dict(title='A minor-monotone parameter characterizing integral Erdős–Pósa duality',status='resolved',formal='Historical conjecture, resolved positively: for every fixed nonempty finite graph H, does there exist a minor-monotone graph parameter p_H taking nonnegative integer values such that, for every minor-closed graph class C, H-minor models have the integral Erdős–Pósa property on C if and only if sup_{G∈C}p_H(G)<∞? The same parameter p_H must work for all choices of C.',definitions='Graphs are finite, undirected and simple. A minor is obtained by deleting vertices or edges and contracting edges, with loops removed and parallel edges suppressed. An H-minor model in G consists of pairwise disjoint connected vertex sets B_v for v∈V(H), with an edge between B_u and B_v for each uv∈E(H); its support is their union. Let pack_H(G) be the largest number of models with mutually disjoint supports, and let τ_H(G) be the minimum number of vertices whose deletion leaves no H minor. The integral Erdős–Pósa property on C means that a function f:N_0→N_0 exists such that τ_H(G)≤f(pack_H(G)) for every G∈C. This one f may depend on H and C, but not on the individual graph. A class is minor-closed if it contains every minor of each of its graphs. A graph parameter is invariant under graph isomorphism and is minor-monotone when G′ a minor of G implies p_H(G′)≤p_H(G). Boundedness on C means one finite bound for all graphs in C. H need not be connected. No efficient evaluation algorithm or uniquely prescribed parameter is part of the conjecture.',question_type='yes_no',answer_criterion='The affirmative answer follows from the published finite obstruction-sequence characterization: for the target class of H-minor-free graphs, take p_H(G) to be the largest order of an obstruction in its fixed finite collection of increasing minor sequences that occurs as a minor of G, using 0 when none occurs. Minor monotonicity and the theorem’s excluded-sequence criterion give exactly the required equivalence.',context_blocks=[b('Packing and deletion measure the same obstruction differently','Packing asks for many vertex-disjoint occurrences of H as a minor. Covering asks for a small common vertex set meeting every such occurrence. An Erdős–Pósa function says that bounded packing forces bounded covering throughout a whole graph class.'),b('The parameter must precede the environment class','Choosing a separate arbitrary parameter after seeing C would weaken the conjecture. Here H alone determines p_H, and boundedness of that one parameter recognizes every minor-closed class where the duality holds.'),b('The later theorem supplies the missing characterization','Paul, Protopapas, Thilikos and Wiederrecht give a finite collection of obstruction sequences for every proper minor-closed target class. A minor-closed environment has integral packing–covering duality precisely when it excludes some member of every sequence. Applying this to H-minor-free target graphs yields the conjectured parameter.', 'solution'),b('Integral and half-integral packing are different','Half-integral packing allows each vertex to belong to two chosen models. The source paper’s half-integral results alone do not settle this card. The later theorem characterizes the integral duality required here. For planar H, the classical integral theorem already holds on all graphs, so the constant parameter p_H=0 suffices.', 'primary')],why='Provides a uniform structural explanation for which minor-closed graph classes support integral packing–covering duality for a fixed graph pattern.',progress=[dict(date='2024',text='The ICALP paper states the minor-monotone parameter characterization as Conjecture 1.',citation='primary'),dict(date='2024-07-16',text='The full obstruction-sequence theorem in arXiv:2407.09671v2 yields the required parameter when the target class consists of H-minor-free graphs.',citation='solution'),dict(date='2024',text='The result is published at FOCS 2024, pp. 31–52.',citation='publication')],references=refs,status_note='Resolved as a consequence of Paul–Protopapas–Thilikos–Wiederrecht, Obstructions to Erdős–Pósa Dualities for Minors, FOCS 2024, Theorem 1.1 in the full version. Checked the original conjecture, integral EP-pair definition, finite obstruction-sequence characterization and its application to H-minor-free graphs, including disconnected H. This is a published-theorem/model match, not an independent proof audit or proof-assistant certificate.',model_self_contained=True,requires_context=False,importance=imp(c,'A general structural characterization of integral minor packing–covering duality.'),review_note='Restored the missing boundedness equivalence and the order of quantifiers. Distinguished integral from half-integral packing and matched the conjecture to the later FOCS theorem.',working_summary=sm(['An Erdős–Pósa property turns a bound on disjoint graph-pattern occurrences into a bound on the vertices needed to hit every occurrence.','The conjecture asked for one minor-monotone parameter for each pattern H that recognizes exactly the minor-closed classes with this property.','The parameter must work uniformly across all such classes.','The same authors’ later FOCS 2024 obstruction theorem gives the required characterization.','This settles the integral question, beyond the earlier half-integral result.'],['primary','solution','publication'])),notes=['Recovered the complete equivalence, graph-minor model and class-uniform quantifiers.','Separated integral duality from half-integral packing and efficient parameter computation.','Checked the FOCS 2024 theorem and recorded the affirmative resolution.'],checked_sources=[r['url'] for r in refs]+['https://focs.computer.org/2024/accepted-papers-for-focs-2024/','https://pure.kaist.ac.kr/en/publications/obstructions-to-erd%C3%B6s-p%C3%B3sa-dualities-for-minors/'])

qpath=DIRECTORY/'queue.json';q=json.loads(qpath.read_text())
for i in ['TCS-2069','TCS-2089']:
    _,c=card(i)
    if not any(x['id']==i for x in q['dispositions']):
        q['dispositions'].append(dict(id=i,title=c['title'],state='resolved',reason=c['status_note'],card='data/cards/'+i+'.json'))
write(qpath,q)
